func TestWriteInterestedIn(t *testing.T) {
	knownFor := map[int64]map[int]float64{
		1: {10: 0.75, 11: 0.25},
		2: {12: 1},
	}
	gi := NewGraphIndex()
	var edges []Edge
	// Enough users to span several output chunks.
	const users = 10_000
	for u := int64(100); u < 100+users; u++ {
		switch u % 4 {
		case 0:
			edges = append(edges, Edge{From: u, To: 1})
		case 1:
			edges = append(edges, Edge{From: u, To: 2})
		case 2:
			edges = append(edges, Edge{From: u, To: 1}, Edge{From: u, To: 2})
		case 3:
			edges = append(edges, Edge{From: u, To: 50}) // not an influencer
		}
	}
	gi.AddEdgesBatch(edges)

	var first []byte
	for _, workers := range []int{1, 3} {
		var buf bytes.Buffer
		n, err := writeInterestedIn(&buf, gi, knownFor, 5, workers)
		if err != nil {
			t.Fatal(err)
		}
		if want := users * 3 / 4; n != want {
			t.Errorf("wrote %d users, want %d", n, want)
		}
		if first == nil {
			first = buf.Bytes()
		} else if !bytes.Equal(first, buf.Bytes()) {
			t.Error("output depends on the number of workers")
		}

		var got map[int64]map[int]float64
		if err := json.Unmarshal(buf.Bytes(), &got); err != nil {
			t.Fatalf("output is not valid JSON: %v", err)
		}
		if len(got) != n {
			t.Fatalf("decoded %d users, want %d", len(got), n)
		}
		for u, want := range map[int64]map[int]float64{
			100: {10: 0.75, 11: 0.25},
			101: {12: 1},
			102: {10: 0.375, 11: 0.125, 12: 0.5},
		} {
			if !reflect.DeepEqual(got[u], want) {
				t.Errorf("user %d: got %v, want %v", u, got[u], want)
			}
		}
		if _, ok := got[103]; ok {
			t.Error("user following no influencer was written")
		}
	}

	var buf bytes.Buffer
	if n, err := writeInterestedIn(&buf, NewGraphIndex(), knownFor, 5, 2); err != nil || n != 0 || buf.String() != "{}\n" {
		t.Errorf("empty graph: got %q, %d, %v", buf.String(), n, err)
	}
}
package simclusters

import (
	"bytes"
	"encoding/json"
	"math"
	"math/rand"
	"os"
	"path/filepath"
	"slices"
	"testing"
)

const (
	e2eGroups      = 12
	e2ePerGroup    = 15
	e2ePoolSize    = 400
	e2eInfluencers = e2eGroups * e2ePerGroup
	e2eUserBase    = 10_000
)

// e2eFollowGraph builds a follow graph of groups of influencers (ids from 1)
// that share an audience: every influencer is followed by 60% of its group's
// pool of users, and every user also follows two random influencers.
func e2eFollowGraph() []Edge {
	r := rand.New(rand.NewSource(1))
	var edges []Edge
	for inf := 0; inf < e2eInfluencers; inf++ {
		pool := e2eUserBase + (inf/e2ePerGroup)*e2ePoolSize
		for u := 0; u < e2ePoolSize; u++ {
			if r.Float64() < 0.6 {
				edges = append(edges, Edge{From: int64(pool + u), To: int64(inf + 1)})
			}
		}
	}
	for u := 0; u < e2eGroups*e2ePoolSize; u++ {
		for i := 0; i < 2; i++ {
			edges = append(edges, Edge{From: int64(e2eUserBase + u), To: int64(r.Intn(e2eInfluencers) + 1)})
		}
	}
	return edges
}

func e2eOptions(t *testing.T) Options {
	opts := DefaultOptions()
	opts.MinFollowers = 50
	opts.NumCommunities = 2 * e2eGroups
	opts.Epochs = 30
	opts.Workers = 4
	opts.OutputDir = t.TempDir()
	return opts
}

func readAssignments(t *testing.T, path string) map[int64]map[int]float64 {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
