			off[u] = out
			copy(adj[out:], adj[start:start+uint64(deg[u])])
			out += uint64(deg[u])
		}
		off[n] = out
		if out < uint64(len(adj))/8*7 {
			adj = slices.Clone(adj[:out])
		} else {
			adj = adj[:out:out]
		}
	}
	gi.off, gi.adj = off, adj
	gi.inDeg = countInDegrees(n, adj, workers)
}

